 import React, { useState, useEffect, useRef } from 'react'
import { useAuth } from '../contexts/AuthContext'
import { supabase } from '../lib/supabase'
import { Camera, Loader, User } from 'lucide-react'
import FullImageModal from './FullImageModal'

export default function ProfilePicture({ 
    size = 'lg', 
    editable = false, 
    userId = null,
    onUpdate 
}) {
    const { user, profile, updateAvatar } = useAuth()
    const [uploading, setUploading] = useState(false)  // ✅ This is defined here
    const [preview, setPreview] = useState(null)
    const [avatarUrl, setAvatarUrl] = useState(null)
    const [showFullImage, setShowFullImage] = useState(false)
    const fileInputRef = useRef(null)

    const isOwn = !userId || userId === user?.id  // ✅ This is defined here

    // ... rest of your original ProfilePicture code

    // ✅ For the upload button, use the variables that are defined
    return (
        <>
            <div className="relative inline-block">
                {/* ... */}
                {editable && isOwn && !uploading && (
                    <button
                        onClick={(e) => {
                            e.stopPropagation()
                            triggerFileInput()
                        }}
                        className="absolute -bottom-1 -right-1 bg-green-600 text-white rounded-full p-1.5 shadow-lg hover:bg-green-700 transition"
                        title="Change profile picture"
                    >
                        <Camera size={14} />
                    </button>
                )}
                {/* ... */}
            </div>
        </>
    )
}
